local BossRankType = {
	CakeShopBoss = 1,
	ParkMiniWorldBoss = 2,
	JapaneseStory = 3,
	MournBoss = 4,
	ParkMiniWorldBossPartition = 5, --分榜
}

--- from: Assets/BundleResources/Prefabs/ActivityMidFestival/12000201/ActivityMidFestivalBossMain.prefab > name: Cell
---@class CommonRankRootCell
---@field Env                            CommonRankRootCell
---@field controller                        Engine.Modules.LuaBehaviour
---@field TextNoReward                    UnityEngine.RectTransform
