---@field Imgbg2                            UnityEngine.RectTransform
---@field Imgbg1                            UnityEngine.RectTransform
---@field Txtranking                        UnityEngine.RectTransform
local CommonRankRootCell = Class('CommonRankRootCell')

--region lifecycle

function CommonRankRootCell:__init()
	self.isIgnore = false
	self.rankType = 1
end

function CommonRankRootCell:__delete()
	self.isIgnore = nil
	self.rankType = nil
end

function CommonRankRootCell:Awake()
	---@type CommonPlayerHeadNode
	self._headNodeScr = CfUtils.GetLuaScr(self.CommonPlayerHeadNode, "Game.Behaviours.CommonPlayerHeadNode")
	---@type PlayerComponent
	self._playerComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
end

function CommonRankRootCell:SetIgnoreClick(ignore)
	self.isIgnore = ignore
end

function CommonRankRootCell:OnDestroy()
	self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
	self:Delete()
	self = nil --lua层的gc需要
end
--endregion lifecycle

--region handler
function CommonRankRootCell:OnClickHeadNodeHandler()
	GameUtils.ShowPlayerInfo(self._rankItem.playerId, {
		{ id = Constants.UITypeIds.CommonActivityBossMain }
	})
end

function CommonRankRootCell:OnClickBtnTeamDetailHandler()
	if self.isIgnore then
		return
	end
	GameUtils.ShowCommonTeamsTipsBoard(self.BtnDetails, self._rankItem.team, nil, nil, self._rankItem.name)
end
--endregion handler

--region public
function CommonRankRootCell:Refresh(rankItemInfo, index, entryCtrl,rankType)
	self._isEven = index % 2 == 0
	self._rankNo = index
	self._rankItem = rankItemInfo
	self.entryCtrl = entryCtrl
	self.rankType = rankType
	self._playerId = self._playerComp:GetPlayerDojo().playerId
	self:RefreshUI()
end
--endregion public

--region private
function CommonRankRootCell:RefreshImgRank()
	CfUtils.SetUISwitchImage(self.ImgRank, self._rankNo)
	CfUtils.SetUISwitchImage(self.ImgRank2, self._rankNo)
	CfUtils.SetUISwitchText(self.Txtranking, self._rankNo)
	CfUtils.FillText(self.Txtranking, self._rankNo)
end

function CommonRankRootCell:RefreshPlayerInfo()
	CfUtils.FillText(self.TxtName, self._rankItem.name)
	CfUtils.FillText(self.TextLevel, "Lv." .. checkString(self._rankItem.level))
	CfUtils.FillText(self.TxtDamage, self._rankItem.score)
	CfUtils.SetActive(self.ImgMyself, checkString(self._rankItem.playerId) == self._playerId)
	self._headNodeScr:FreshAvatarFrame(self._rankItem.avatar, self._rankItem.avatarFrame)
	if not self.isIgnore then
		self._headNodeScr:SetCallBack(Bind(self, self.OnClickHeadNodeHandler))
	end
end

function CommonRankRootCell:RefreshRewardsInfo()
	local rewards = self:GetRankRewards(1)
	if table.count(rewards) == 0 then
		CfUtils.SetActive(self.TextNoReward, true)
		CfUtils.SetActive(self.CommonGoodsList , false)
		return
	end
	CfUtils.SetActive(self.TextNoReward, false)
	CfUtils.SetActive(self.CommonGoodsList , true)
	---@type CommonGoodsList
	local scr = CfUtils.GetLuaScr(self.CommonGoodsList, "Game.Behaviours.CommonGoodsList")
	scr:FreshBaseUI(rewards)
end

function CommonRankRootCell:GetRankRewards(type)
	local allVoList = self:GetRankRewardsByType()
	local rewards = {}
	for i, item in ipairs(allVoList) do
		---@type MidFestivalBossRankRewardVo
		local vo = item
		if vo.type == type then
			if self._rankNo >= vo.upperLimit and self._rankNo <= vo.lowerLimit then
				local rewardsCount = #vo.reward
				for i = 1, rewardsCount do
					table.insert(rewards, {
						goodsId = vo.reward[i],
						num = vo.rewardNum[i]
					})
				end
			end
		end
	end
	return rewards
end

function CommonRankRootCell:GetRankRewardsByType()
	if self.rankType == 1 then
		return self.entryCtrl:GetBossRankRewardVos()
	else
		return self.entryCtrl:GetSplitRankRewardsVos()
	end
	return {}
end

function CommonRankRootCell:RefreshTeamInfo()
	if not self.isIgnore then
		CfUtils.SetActive(self.BtnDetails,true)
		SetButtonAction(self.BtnDetails, Bind(self, self.OnClickBtnTeamDetailHandler))
	else
		CfUtils.SetActive(self.BtnDetails,false)
	end
end

function CommonRankRootCell:RefreshUI()
	CfUtils.SetActive(self.Imgbg1, not self._isEven)
	CfUtils.SetActive(self.Imgbg2, self._isEven)
	
	self:RefreshImgRank()
	self:RefreshPlayerInfo()
	self:RefreshRewardsInfo()
	self:RefreshTeamInfo()
end
--endregion private

--region get / set
--endregion get / set

return CommonRankRootCell